 t=(base/f).read_text(encoding='utf-8-sig',errors='replace');ls=t.splitlines(); symbols=[{'line':i,'symbol':v.strip()[:240]} for i,v in enumerate(ls,1) if re.search(r'^\s*(?:(?:public|protected|private)\s+)(?:static\s+)?(?:final\s+)?[\w.<>,\[\] ]+\s+[A-Za-z_]\w*\s*\(',v)][:50];tag='com/eva/ro/contab/'
 k=None
 if tag in f and f.endswith('.java'):k=tag+f.split(tag,1)[1][:-5]+'.class'
 zhash={}
 if k:
  for mode,zz in [('source_binary','cod-master-contab.jar'),('installed_binary','com.eva.ro.contab_13.0.0.jar')]:
   with zipfile.ZipFile(sec/zz) as z:zashes=hashlib.sha256(z.read(k)).hexdigest() if k in z.namelist() else None
   zhash[mode]=zashes
 class_name=k[:-6].replace('/','.') if k else None
 return {'path':f,'sha':sha,'sha256':dig(base/f),'lines':len(ls),'method_declarations':symbols,'bytecode_entry':k,'bytecode':zhash,'AD_entry':metaf.get(class_name),'level':'source, bytecode and AD metadata. The listed declarations alone are not a runtime trace.'}
